package com.pousada;

import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import org.junit.jupiter.api.*;

import static io.restassured.RestAssured.*;
import static org.hamcrest.Matchers.*;

@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
public class AppIT {
    private static Thread serverThread;
    private static final int TEST_PORT = 7071;

    @BeforeAll
    public static void setUp() {
        System.setProperty("PORT", String.valueOf(TEST_PORT));
        RestAssured.port = TEST_PORT;
        RestAssured.baseURI = "http://localhost";

        serverThread = new Thread(() -> App.main(new String[]{}));
        serverThread.setDaemon(true);
        serverThread.start();

        try {
            Thread.sleep(2000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    @Test
    @Order(1)
    public void testGetRooms() {
        given()
            .when()
            .get("/rooms")
            .then()
            .statusCode(200)
            .body("size()", is(5))
            .body("[0].number", is("101"))
            .body("[0].type", is("STANDARD"))
            .body("[0].capacity", is(2))
            .body("[0].nightlyRate", is(249.90f));
    }

    @Test
    @Order(2)
    public void testCreateReservationWithCpf() {
        String requestBody = """
            {
                "roomNumber": "101",
                "guestName": "João Silva",
                "guestEmail": "joao@example.com",
                "guestCpf": "123.456.789-00",
                "checkIn": "2027-03-10",
                "checkOut": "2027-03-12",
                "guests": 2,
                "ratePlan": "STANDARD"
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(requestBody)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .body("id", is(1))
            .body("roomNumber", is("101"))
            .body("guestName", is("João Silva"))
            .body("guestCpf", is("123.456.789-00"))
            .body("companyName", nullValue())
            .body("companyCnpj", nullValue())
            .body("guestPassport", nullValue())
            .body("guestCountry", nullValue())
            .body("nights", is(2))
            .body("status", is("PENDING"))
            .body("amountPaid", is(0.0f));
    }

    @Test
    @Order(3)
    public void testCreateReservationWithCnpj() {
        String requestBody = """
            {
                "roomNumber": "201",
                "guestName": "Ana Souza",
                "guestEmail": "ana@example.com",
                "companyName": "Tecnosul Ltda",
                "companyCnpj": "12.345.678/0001-90",
                "checkIn": "2027-03-10",
                "checkOut": "2027-03-12",
                "guests": 2,
                "ratePlan": "STANDARD"
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(requestBody)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .body("id", is(2))
            .body("companyName", is("Tecnosul Ltda"))
            .body("companyCnpj", is("12.345.678/0001-90"));
    }

    @Test
    @Order(4)
    public void testCreateReservationWithPassport() {
        String requestBody = """
            {
                "roomNumber": "202",
                "guestName": "John Smith",
                "guestEmail": "john@example.com",
                "guestPassport": "X1234567",
                "guestCountry": "United Kingdom",
                "checkIn": "2027-03-10",
                "checkOut": "2027-03-12",
                "guests": 2,
                "ratePlan": "NON_REFUNDABLE"
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(requestBody)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .body("id", is(3))
            .body("guestPassport", is("X1234567"))
            .body("guestCountry", is("United Kingdom"))
            .body("discount", greaterThan(0.0f));
    }

    @Test
    @Order(5)
    public void testConfirmReservation() {
        given()
            .when()
            .post("/reservations/1/confirmation")
            .then()
            .statusCode(200)
            .body("status", is("CONFIRMED"))
            .body("amountPaid", greaterThan(0.0f));

        given()
            .when()
            .get("/messages")
            .then()
            .statusCode(200)
            .body("size()", is(1))
            .body("[0].channel", is("EMAIL"))
            .body("[0].to", is("joao@example.com"))
            .body("[0].subject", is("Reserva confirmada - Pousada Maré Alta"))
            .body("[0].body", containsString("João Silva"))
            .body("[0].body", containsString("Comprovante de reserva nº 1"));
    }

    @Test
    @Order(6)
    public void testCheckIn() {
