@BeforeAll
public static void setUp() throws Exception {
    System.setProperty("PORT", String.valueOf(TEST_PORT));
    RestAssured.port = TEST_PORT;
    RestAssured.baseURI = "http://localhost";

    serverThread = new Thread(() -> App.main(new String[]{}));
    serverThread.setDaemon(true);
    serverThread.start();

    int maxRetries = 30;
    for (int i = 0; i < maxRetries; i++) {
        try {
            Thread.sleep(500);
            given().get("/rooms").then().statusCode(200);
            System.out.println("Server started successfully");
            return;
        } catch (Exception e) {
            if (i == maxRetries - 1) {
                throw new RuntimeException("Server failed to start after " + (maxRetries * 500) + "ms", e);
            }
        }
    }
}

