package com.pousada;

import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import org.junit.jupiter.api.*;

import static io.restassured.RestAssured.*;
import static org.hamcrest.Matchers.*;

@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
public class AppIT {
    private static Thread serverThread;
    private static final int TEST_PORT = 7071;

    @BeforeAll
    public static void setUp() {
        System.setProperty("PORT", String.valueOf(TEST_PORT));
        RestAssured.port = TEST_PORT;
        RestAssured.baseURI = "http://localhost";

        serverThread = new Thread(() -> App.main(new String[]{}));
        serverThread.setDaemon(true);
        serverThread.start();

        try {
            Thread.sleep(2000);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    @Test
    @Order(1)
    public void testGetRooms() {
        given()
            .when()
            .get("/rooms")
            .then()
            .statusCode(200)
            .body("size()", is(5))
            .body("[0].number", is("101"))
            .body("[0].type", is("STANDARD"))
            .body("[0].capacity", is(2))
            .body("[0].nightlyRate", is(249.90f));
    }

    @Test
    @Order(2)
    public void testCreateReservationWithCpf() {
        String requestBody = """
            {
                "roomNumber": "101",
                "guestName": "João Silva",
                "guestEmail": "joao@example.com",
                "guestCpf": "123.456.789-00",
                "checkIn": "2027-03-10",
                "checkOut": "2027-03-12",
                "guests": 2,
                "ratePlan": "STANDARD"
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(requestBody)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .body("id", is(1))
            .body("roomNumber", is("101"))
            .body("guestName", is("João Silva"))
            .body("guestCpf", is("123.456.789-00"))
            .body("companyName", nullValue())
            .body("companyCnpj", nullValue())
            .body("guestPassport", nullValue())
            .body("guestCountry", nullValue())
            .body("nights", is(2))
            .body("status", is("PENDING"))
            .body("amountPaid", is(0.0f));
    }

    @Test
    @Order(3)
    public void testCreateReservationWithCnpj() {
        String requestBody = """
            {
                "roomNumber": "201",
                "guestName": "Ana Souza",
                "guestEmail": "ana@example.com",
                "companyName": "Tecnosul Ltda",
                "companyCnpj": "12.345.678/0001-90",
                "checkIn": "2027-03-10",
                "checkOut": "2027-03-12",
                "guests": 2,
                "ratePlan": "STANDARD"
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(requestBody)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .body("id", is(2))
            .body("companyName", is("Tecnosul Ltda"))
            .body("companyCnpj", is("12.345.678/0001-90"));
    }

    @Test
    @Order(4)
    public void testCreateReservationWithPassport() {
        String requestBody = """
            {
                "roomNumber": "202",
                "guestName": "John Smith",
                "guestEmail": "john@example.com",
                "guestPassport": "X1234567",
                "guestCountry": "United Kingdom",
                "checkIn": "2027-03-10",
                "checkOut": "2027-03-12",
                "guests": 2,
                "ratePlan": "NON_REFUNDABLE"
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(requestBody)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .body("id", is(3))
            .body("guestPassport", is("X1234567"))
            .body("guestCountry", is("United Kingdom"))
            .body("discount", greaterThan(0.0f));
    }

    @Test
    @Order(5)
    public void testConfirmReservation() {
        given()
            .when()
            .post("/reservations/1/confirmation")
            .then()
            .statusCode(200)
            .body("status", is("CONFIRMED"))
            .body("amountPaid", greaterThan(0.0f));

        given()
            .when()
            .get("/messages")
            .then()
            .statusCode(200)
            .body("size()", is(1))
            .body("[0].channel", is("EMAIL"))
            .body("[0].to", is("joao@example.com"))
            .body("[0].subject", is("Reserva confirmada - Pousada Maré Alta"))
            .body("[0].body", containsString("João Silva"))
            .body("[0].body", containsString("Comprovante de reserva nº 1"));
    }

    @Test
    @Order(6)
    public void testCheckIn() {
        given()
            .when()
            .post("/reservations/1/check-in")
            .then()
            .statusCode(200)
            .body("status", is("CHECKED_IN"));
    }

    @Test
    @Order(7)
    public void testCheckOut() {
        given()
            .when()
            .post("/reservations/1/check-out")
            .then()
            .statusCode(200)
            .body("title", is("Comprovante de reserva"))
            .body("reservationId", is(1))
            .body("text", containsString("Comprovante de reserva nº 1"))
            .body("text", containsString("João Silva (CPF 123.456.789-00)"));
    }

    @Test
    @Order(8)
    public void testGetDocument() {
        given()
            .when()
            .post("/reservations/2/confirmation")
            .then()
            .statusCode(200);

        given()
            .when()
            .get("/reservations/2/document")
            .then()
            .statusCode(200)
            .body("title", is("Fatura de hospedagem"))
            .body("text", containsString("Empresa: Tecnosul Ltda (CNPJ 12.345.678/0001-90)"))
            .body("text", containsString("ISS retido (5%)"));
    }

    @Test
    @Order(9)
    public void testCancelReservation() {
        given()
            .when()
            .post("/reservations/3/confirmation")
            .then()
            .statusCode(200);

        given()
            .when()
            .post("/reservations/3/cancellation")
            .then()
            .statusCode(200)
            .body("status", is("CANCELLED"))
            .body("refund", is(0.0f));
    }

    @Test
    @Order(10)
    public void testOccupancyReport() {
        given()
            .queryParam("date", "2027-03-10")
            .when()
            .get("/reports/occupancy")
            .then()
            .statusCode(200)
            .contentType("text/csv; charset=utf-8")
            .body(containsString("room,type,reservation,check_in,check_out"))
            .body(containsString("101,STANDARD,1,2027-03-10,2027-03-12"))
            .body(containsString("201,DELUXE,2,2027-03-10,2027-03-12"))
            .body(containsString("total,2/5"));
    }

    @Test
    @Order(11)
    public void testRevenueReport() {
        given()
            .queryParam("month", "2027-03")
            .when()
            .get("/reports/revenue")
            .then()
            .statusCode(200)
            .contentType("text/csv; charset=utf-8")
            .body(containsString("reservation,room,check_in,check_out,status,amount"))
            .body(containsString("1,101,2027-03-10,2027-03-12,CHECKED_OUT"))
            .body(containsString("total,"));
    }

    @Test
    @Order(12)
    public void testRoomNotFound() {
        String requestBody = """
            {
                "roomNumber": "999",
                "guestName": "Test",
                "guestEmail": "test@example.com",
                "guestCpf": "111.111.111-11",
                "checkIn": "2027-03-10",
                "checkOut": "2027-03-12",
                "guests": 1,
                "ratePlan": "STANDARD"
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(requestBody)
            .when()
            .post("/reservations")
            .then()
            .statusCode(404)
            .body("error", is("ROOM_NOT_FOUND"));
    }

    @Test
    @Order(13)
    public void testCapacityExceeded() {
        String requestBody = """
            {
                "roomNumber": "101",
                "guestName": "Test",
                "guestEmail": "test@example.com",
                "guestCpf": "111.111.111-11",
                "checkIn": "2027-04-10",
                "checkOut": "2027-04-12",
                "guests": 5,
                "ratePlan": "STANDARD"
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(requestBody)
            .when()
            .post("/reservations")
            .then()
            .statusCode(422)
            .body("error", is("CAPACITY_EXCEEDED"));
    }

    @Test
    @Order(14)
    public void testInvalidIdentification() {
        String requestBody = """
            {
                "roomNumber": "101",
                "guestName": "Test",
                "guestEmail": "test@example.com",
                "checkIn": "2027-05-10",
                "checkOut": "2027-05-12",
                "guests": 1,
                "ratePlan": "STANDARD"
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(requestBody)
            .when()
            .post("/reservations")
            .then()
            .statusCode(400)
            .body("error", is("INVALID_REQUEST"));
    }

    @Test
    @Order(15)
    public void testHighSeasonPricing() {
        String requestBody = """
            {
                "roomNumber": "102",
                "guestName": "Test Summer",
                "guestEmail": "summer@example.com",
                "guestCpf": "222.222.222-22",
                "checkIn": "2027-07-10",
                "checkOut": "2027-07-12",
                "guests": 2,
                "ratePlan": "STANDARD"
            }
            """;

        given()
            .contentType(ContentType.JSON)
            .body(requestBody)
            .when()
            .post("/reservations")
            .then()
            .statusCode(201)
            .body("subtotal", is(599.76f));
    }
}

